insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('rockphysics', 'intermediate', 'module', 'm01-putting-the-fluid-in-the-rock', 1, 'What does the Professional tier add to the Associate tier''s work?', '["It puts the ingredients into a rock with porosity and predicts a fluid change.", "It computes the fluid properties at reservoir conditions rather than at standard ones.", "It replaces the Voigt Reuss Hill average with a more accurate mineral mixing rule.", "It predicts what a seismic survey would record from the top of the reservoir."]'::jsonb, 0, 'The tier below computed fluids and a mineral frame, which are properties of substances rather than of rocks. Predicting the seismic response is the Expert tier.'),
  ('rockphysics', 'intermediate', 'module', 'm01-putting-the-fluid-in-the-rock', 2, 'What state was the Ekene sand in when it was logged?', '["Gas saturated, which is why the substitution runs to brine.", "Brine saturated, since the log was recorded below the contact.", "Partially saturated at Sw 0.8, matching the Associate capstone.", "Unknown, which is why the tier computes both cases."]'::jsonb, 1, 'The substitution runs from the logged brine state to a predicted gas state. Everything in the tier depends on that starting state being correctly identified.'),
  ('rockphysics', 'intermediate', 'module', 'm01-putting-the-fluid-in-the-rock', 3, 'Why is the shear modulus computed from the shear velocity alone?', '["Because the shear velocity is measured more accurately than the compressional one.", "Because the bulk modulus contributes nothing to a shear wave in any medium.", "Because $v_s$ depends only on $\\mu$ and $\\rho$, so nothing else appears in it.", "Because the shear log is recorded at a different frequency from the sonic."]'::jsonb, 2, '$v_s = \sqrt{\mu/\rho}$, so the density and the shear velocity determine the shear modulus with no other input. The bulk modulus genuinely does not appear, which is a physical fact rather than a convenience.'),
  ('rockphysics', 'intermediate', 'module', 'm01-putting-the-fluid-in-the-rock', 4, 'Compute the shear modulus of a rock logging 2200 kg/m3 and 1500 m/s.', '["4.95 GPa.", "3.30 GPa, from half the product.", "7.29 GPa.", "9.90 GPa."]'::jsonb, 0, '$\mu = \rho v_s^2 = 2200 \times 1500^2 = 4.95 \times 10^9$ Pa. The value 7.29 GPa is the Ekene sand''s, at a different density and shear velocity.'),
  ('rockphysics', 'intermediate', 'module', 'm01-putting-the-fluid-in-the-rock', 5, 'Why are the Ekene values of 7.29 and 13.32 GPa graded to only 0.01?', '["Because the tolerance matches the precision of the density log.", "Because both are exact, with no rounding.", "Because they are intermediate values rather than final answers.", "Because the engine stores them as 32 bit floats."]'::jsonb, 1, '$2250 \times 1800^2 = 7.29$e9 and $2250 \times 3200^2 - \tfrac{4}{3}(7.29$e9$) = 13.32$e9 are exact in binary floating point, so any disagreement is a mistake rather than a rounding difference.'),
  ('rockphysics', 'intermediate', 'module', 'm01-putting-the-fluid-in-the-rock', 6, 'What are the two directions a substitution runs in?', '["Backwards through the mineral frame, then forwards through the pore fluid.", "Forwards to predict the gas case, then backwards to check the brine case.", "Backwards to recover the dry frame, then forwards to add a new fluid.", "Upwards from the log to the seismic, then downwards to the core."]'::jsonb, 2, 'Inverse Gassmann strips the logged fluid out and leaves the frame; the forward relation puts a different fluid in. That two direction structure is the whole tier.'),
  ('rockphysics', 'intermediate', 'module', 'm01-putting-the-fluid-in-the-rock', 7, 'Which quantity does the substitution carry through untouched?', '["The bulk density, since the mineral mass does not change.", "The saturated bulk modulus, since the frame is unchanged.", "The porosity, since no rock is added or removed.", "The shear modulus, since fluids have no shear stiffness."]'::jsonb, 3, 'The porosity is also unchanged, but it is an input rather than something the substitution computes. The shear modulus is the quantity Gassmann''s relation deliberately says nothing about.'),
  ('rockphysics', 'intermediate', 'module', 'm01-putting-the-fluid-in-the-rock', 8, 'How is the substituted bulk density obtained?', '["$\\rho + \\phi(\\rho_{fl}'' - \\rho_{fl})$, which is mass bookkeeping.", "From the forward Gassmann relation, alongside the new bulk modulus.", "From the substituted velocities and the shear modulus.", "By scaling the logged density by the ratio of the fluid moduli."]'::jsonb, 0, '$\rho'' = \rho + \phi(\rho_{fl}'' - \rho_{fl})$, which at Ekene gives 2038.7104517793223 kg/m3. No equation from rock physics appears in it.'),
  ('rockphysics', 'intermediate', 'module', 'm01-putting-the-fluid-in-the-rock', 9, 'What happens to the two velocities when brine is replaced by gas at Ekene?', '["Both fall, the compressional by rather more than the shear.", "The compressional falls and the shear rises.", "Both rise, the shear by more.", "The compressional rises and the shear falls."]'::jsonb, 1, 'The compressional velocity falls from 3200 to 2905.6972280296195 and the shear rises from 1800 to 1890.9758806113214. Two velocities moving in opposite directions from one fluid change is the signature of the method.'),
  ('rockphysics', 'intermediate', 'module', 'm01-putting-the-fluid-in-the-rock', 10, 'Which of the panel''s three controls is a measurement rather than an assumption?', '["The mineral modulus, since it comes from the lithology.", "The porosity, since it comes from a petrophysical model of the log.", "None of them: the saturation asks a question.", "The water saturation, since it is read from the resistivity log."]'::jsonb, 2, 'The saturation control asks what if. The porosity and the mineral modulus are both derived quantities carrying the uncertainty of the models behind them.'),
  ('rockphysics', 'intermediate', 'module', 'm01-putting-the-fluid-in-the-rock', 11, 'What does the panel''s round trip tile show?', '["The change in velocity over a full cycle of saturation.", "The difference between the forward and inverse Gassmann results.", "The velocity that would be measured on a second logging run.", "The result of substituting the original fluid back."]'::jsonb, 3, 'It must return the logged 3200.0000 and 1800.0000 exactly, which tests the whole chain from moduli through both Gassmann directions and back to velocities.'),
  ('rockphysics', 'intermediate', 'module', 'm01-putting-the-fluid-in-the-rock', 12, 'Which conversion is lossless in both directions?', '["Velocities and density to moduli, and moduli and density back.", "Saturated modulus to dry frame and back through Gassmann.", "Mineral composition to mineral frame and back.", "Fluid saturation to fluid modulus and back through Wood''s equation."]'::jsonb, 0, '$\mu = \rho v_s^2$ and $K = \rho v_p^2 - \tfrac{4}{3}\mu$ invert exactly, so any error in a substitution comes from the substitution rather than from getting into or out of moduli.'),
  ('rockphysics', 'intermediate', 'module', 'm01-putting-the-fluid-in-the-rock', 13, 'Which four properties of the Associate tier''s work does this tier reuse unchanged?', '["The mineral frame, which becomes the dry frame after correcting for porosity.", "The conditions, and so the fluid moduli computed at them.", "The Wood mixture at Sw 0.8, which becomes the capstone pore fluid.", "The bound spread, which sets the uncertainty on the substituted velocity."]'::jsonb, 1, '60 degC, 25 MPa, 35,000 ppm brine and 0.6 gravity gas give the brine and gas properties this tier substitutes. The mineral frame is emphatically not the dry frame.'),
  ('rockphysics', 'intermediate', 'module', 'm01-putting-the-fluid-in-the-rock', 14, 'What does this tier not attempt?', '["Estimating a shear velocity where none was recorded.", "Recovering the dry frame from a logged point.", "Predicting the seismic amplitude at the reservoir top.", "Predicting the density of the substituted rock."]'::jsonb, 2, 'That is the Expert tier, which puts a shale over the substituted sand and computes the reflection. This tier stops at the rock.'),
  ('rockphysics', 'intermediate', 'module', 'm01-putting-the-fluid-in-the-rock', 15, 'A rock logs 2900 m/s, 1500 m/s and 2200 kg/m3. What is its saturated bulk modulus?', '["6.600 GPa.", "18.502 GPa.", "13.320 GPa.", "11.902 GPa."]'::jsonb, 3, '$\mu = 4.95$ GPa, $\rho v_p^2 = 18.502$ GPa, and $18.502 - \tfrac{4}{3}(4.95) = 18.502 - 6.6 = 11.902$ GPa. The figure 18.502 is $\rho v_p^2$ before the shear term is removed.'),
  ('rockphysics', 'intermediate', 'module', 'm02-the-dry-frame', 1, 'What does inverse Gassmann separate?', '["The frame''s contribution to the stiffness from the fluid''s share of it.", "The mineral grains'' stiffness from the cement between them.", "The compressional contribution from the shear contribution.", "The measured part of the log from the modelled part of it."]'::jsonb, 0, 'A saturated rock resists compression because the frame resists and because the trapped fluid resists. The inverse relation removes the fluid''s share and leaves 7.350343061720982 GPa.'),
  ('rockphysics', 'intermediate', 'module', 'm02-the-dry-frame', 2, 'How much of the Ekene sand''s saturated bulk modulus is supplied by the brine?', '["About 5 percent, which is why the substitution is subtle.", "About 45 percent, which is 5.9697 GPa of the 13.32.", "About 80 percent, matching the Biot coefficient.", "About 25 percent, matching the porosity of 0.25."]'::jsonb, 1, '$13.32 - 7.350343061720982 = 5.9697$ GPa, which is 44.8 percent of the saturated value. If it were a few percent there would be no such thing as a direct hydrocarbon indicator.'),
  ('rockphysics', 'intermediate', 'module', 'm02-the-dry-frame', 3, 'Why is the dry frame modulus far below the mineral frame modulus?', '["The dry frame includes the compliance of the residual pore water.", "The mineral frame is computed at surface conditions and the dry frame at depth.", "Porosity removes material and grain contacts carry the load.", "The Voigt Reuss Hill average deliberately overestimates the mineral stiffness."]'::jsonb, 2, '7.350343061720982 against 30.87940062475596 GPa. Grains touch over a tiny fraction of their surface, so the contacts rather than the grain interiors control the frame.'),
  ('rockphysics', 'intermediate', 'module', 'm02-the-dry-frame', 4, 'What is the Biot coefficient of the Ekene sand?', '["0.80, so the frame is compliant and fluid sensitive.", "0.25, matching the porosity of the rock.", "0.55, the ratio of the dry frame to the saturated modulus.", "0.20, one minus the mineral modulus over the dry frame."]'::jsonb, 0, '$1 - 7.350343061720982/37 = 0.8013$. A value near 1 means a compliant frame in a stiff mineral, where a fluid change matters a great deal.'),
  ('rockphysics', 'intermediate', 'module', 'm02-the-dry-frame', 5, 'What happens if the mineral modulus is used where the dry frame belongs?', '["The substitution over-predicts the fluid effect by a factor of four.", "The Biot coefficient goes near zero and the fluid appears to do nothing.", "The inverse relation refuses to run, since the input is out of range.", "The shear modulus is corrupted and the shear velocity comes out badly wrong."]'::jsonb, 1, 'With $K_{dry}$ and $K_{min}$ nearly equal, $1 - K_{dry}/K_{min}$ collapses, and Gassmann concludes the frame is almost solid so a fluid can add almost nothing.'),
  ('rockphysics', 'intermediate', 'module', 'm02-the-dry-frame', 6, 'Why does a fluid have exactly zero shear modulus?', '["Shear waves cannot propagate through it, so none is measured.", "Its molecules are too far apart to transmit a shear stress.", "A fluid at rest has no restoring force against a change of shape.", "Its shear stiffness is below the resolution of any logging tool."]'::jsonb, 2, 'That is what being a fluid means, so the value is exactly zero rather than very small. It is why $\mu_{sat} = \mu_{dry}$ is an exact statement within Gassmann''s assumptions.'),
  ('rockphysics', 'intermediate', 'module', 'm02-the-dry-frame', 7, 'Which frequency assumption does Gassmann''s relation carry?', '["That the fluid is incompressible at the frequency of interest.", "That the wave frequency matches the frequency the log was recorded at.", "That the seismic and sonic frequencies give the same answer.", "That loading is slow enough for pore pressure to equilibrate."]'::jsonb, 3, 'It is a low frequency theory. At sonic and ultrasonic frequencies the fluid cannot equilibrate between pores during a cycle, the rock behaves stiffer, and the shear modulus can move a little.'),
  ('rockphysics', 'intermediate', 'module', 'm02-the-dry-frame', 8, 'Vary the mineral modulus from 35 to 40 GPa. What happens to the predicted gas velocity?', '["It falls by about 60 m/s, from 2931.4 down to 2871.7 m/s.", "It rises by about 60 m/s, since a stiffer mineral gives a stiffer rock.", "It falls by about 320 m/s, matching the porosity sensitivity.", "It does not move, since the mineral modulus cancels out of the substitution."]'::jsonb, 0, 'A stiffer assumed mineral attributes more of the observed saturated stiffness to the material, so less is attributed to the frame, and a softer frame predicts a lower gas velocity.'),
  ('rockphysics', 'intermediate', 'module', 'm02-the-dry-frame', 9, 'Vary the porosity from 0.20 to 0.30. What happens to the predicted gas velocity?', '["It falls by about 324 m/s, since more pore means a softer rock.", "It rises by about 324 m/s, from 2709.64 to 3033.82.", "It rises by about 60 m/s, the same as the mineral modulus range.", "It stays within 20 m/s, since porosity enters both directions and cancels."]'::jsonb, 1, 'A higher assumed porosity attributes more of the logged stiffness to the frame, so the recovered dry frame rises from 5.356 to 8.546 GPa and the gas case velocity rises from 2709.6398569624603 to 3033.8186110096503 m/s. Porosity enters three times: how much fluid to remove, how much to add, and how much of the bulk density is fluid.'),
  ('rockphysics', 'intermediate', 'module', 'm02-the-dry-frame', 10, 'Where should the effort go when improving a substitution?', '["Into the fluid modulus, which enters as a compliance.", "Into the mineral model, which is the least constrained input.", "Into the porosity, which is five times more leveraged.", "Into the shear log, which fixes the modulus that never changes."]'::jsonb, 2, 'Ten porosity units move the answer by 324 m/s against 60 m/s for a 5 GPa range of mineral modulus. Improving the porosity from a guess to a good petrophysical answer buys five times as much.'),
  ('rockphysics', 'intermediate', 'module', 'm02-the-dry-frame', 11, 'What does the engine do when inverse Gassmann''s inputs are inconsistent?', '["It falls back to a constant frame estimated from the porosity.", "It returns a NaN, which the caller must check for.", "It clips the dry frame to the mineral modulus and continues.", "It throws an error naming the reason."]'::jsonb, 3, 'A wrong dry frame propagates silently into a velocity that looks plausible, so refusing is deliberate. The two guards are that the frame must be positive and below the mineral modulus.'),
  ('rockphysics', 'intermediate', 'module', 'm02-the-dry-frame', 12, 'At which end of the porosity range does the guard fire for the Ekene sand?', '["At low porosity, anywhere below about 0.14.", "At high porosity, above about 0.45.", "At both ends, outside roughly 0.15 to 0.40.", "At neither. The guard never fires for a rock this soft."]'::jsonb, 0, 'Explaining 13.32 GPa with almost no fluid needs a frame stiffer than the mineral. The recovered frame rises with porosity and never approaches 37 GPa at the top end, reaching only 12.0 GPa at a porosity of 0.95.'),
  ('rockphysics', 'intermediate', 'module', 'm02-the-dry-frame', 13, 'What is the dry frame modulus at a porosity of 0.14, one step before the guard fires?', '["About 5.4 GPa, close to the 0.20 value.", "About 0.027 GPa, which is essentially zero.", "About 37 GPa, equal to the mineral modulus.", "About 7.35 GPa, unchanged from the capstone value."]'::jsonb, 1, 'The answer is already meaningless one step before the exception arrives, which is the general lesson: an error is the last warning you get rather than the first.'),
  ('rockphysics', 'intermediate', 'module', 'm02-the-dry-frame', 14, 'Which of Gassmann''s assumptions fails without producing an error?', '["A negative recovered dry frame modulus.", "A dry frame above the mineral modulus.", "Unconnected vuggy porosity, which breaks pressure equilibration.", "A fluid modulus of zero."]'::jsonb, 2, 'Strong anisotropy and a reactive frame are the same kind of failure. The other three are caught by the guards, which is exactly why they are the less dangerous cases.'),
  ('rockphysics', 'intermediate', 'module', 'm02-the-dry-frame', 15, 'Which quantity is unaffected by every assumption in this module?', '["The Biot coefficient, which is a ratio.", "The dry frame, once the porosity is fixed.", "The saturated bulk modulus of the gas case.", "The shear modulus, computed from the log alone."]'::jsonb, 3, '$\mu = \rho v_s^2$ needs only the density and shear velocity from the log. Neither the porosity nor the mineral modulus can touch it, which is why it is the one fixed point in the tier.'),
  ('rockphysics', 'intermediate', 'module', 'm03-substituting-the-fluid', 1, 'In the forward Gassmann relation, how does the fluid modulus enter?', '["As a compliance, in the term $\\phi/K_{fl}$ in the denominator.", "Directly, as a stiffness added to the dry frame modulus.", "As a weighting on the Biot coefficient in the numerator.", "Through the mineral modulus, which it modifies before the summation."]'::jsonb, 0, 'Because compliances add, a soft fluid dominates that denominator and contributes almost nothing to the rock''s stiffness. That structure is why the gas effect saturates so quickly.'),
  ('rockphysics', 'intermediate', 'module', 'm03-substituting-the-fluid', 2, 'What is the saturated bulk modulus of the Ekene gas case?', '["13.32 GPa, unchanged from the brine case.", "7.492988063073051 GPa, close to the dry frame.", "7.350343061720982 GPa, equal to the dry frame.", "2.6978112899395996 GPa, the brine value."]'::jsonb, 1, 'The gas adds only 0.1426 GPa to the 7.350343061720982 GPa frame, against the brine''s 5.9697 GPa. A gas filled rock is very nearly a dry rock in compression.'),
  ('rockphysics', 'intermediate', 'module', 'm03-substituting-the-fluid', 3, 'How much stiffness does the gas add compared with the brine?', '["About the same, since both are fluids.", "About 5 times less.", "About 42 times less.", "About 48 times less, matching the modulus ratio."]'::jsonb, 2, '0.1426 GPa against 5.9697 GPa. The fluid moduli themselves differ by 48 times, and the rock''s response differs by less because the frame carries most of the load either way.'),
  ('rockphysics', 'intermediate', 'module', 'm03-substituting-the-fluid', 4, 'What would the forward relation return for a fluid of zero bulk modulus?', '["The dry frame modulus exactly.", "Zero, since a fluid with no stiffness gives a rock with none.", "The mineral modulus, since the pore contributes nothing.", "An error, since a zero modulus is not physical."]'::jsonb, 0, 'The term $\phi/K_{fl}$ goes to infinity, the fraction goes to zero, and $K_{sat}$ returns $K_{dry}$. That is the definition of the dry frame, and it is why the gas case sits so close to it.'),
  ('rockphysics', 'intermediate', 'module', 'm03-substituting-the-fluid', 5, 'What is the Ekene gas case bulk density and where does it come from?', '["2038.7104517793223 kg/m3, from the forward Gassmann relation.", "2038.7104517793223 kg/m3, from simple mass bookkeeping.", "2250 kg/m3, since the substitution does not move the density.", "2192.9518219804170 kg/m3, from the Wood mixture at Sw 0.73."]'::jsonb, 1, '$2250 + 0.25(172.66679461728904 - 1017.8249875)$. No equation from rock physics appears in it, and it involves none of Gassmann''s assumptions.'),
  ('rockphysics', 'intermediate', 'module', 'm03-substituting-the-fluid', 6, 'What does the implied grain density check test?', '["The mineral modulus, against the lithology model.", "The fluid density, against the conditions it was computed at.", "The porosity, against an independent mineral expectation.", "The shear modulus, against the density log."]'::jsonb, 2, '$(\rho - \phi\rho_{fl})/(1-\phi)$ gives 2660.7 kg/m3 at Ekene, consistent with a 70/30 quartz and clay mixture. It costs one line and it tests the most leveraged assumption in the tier.'),
  ('rockphysics', 'intermediate', 'module', 'm03-substituting-the-fluid', 7, 'A 2250 kg/m3 sand is handed to you with an assumed porosity of 0.15. What does the grain density check say?', '["It cannot be computed without the shear velocity.", "2661 kg/m3, consistent with quartz and clay.", "2849 kg/m3, high but possible with heavy minerals.", "2467 kg/m3, below every common clastic mineral."]'::jsonb, 3, 'No clastic mineral mixture gives 2467, so the porosity is rejected on density grounds alone. That same porosity would also give a dry frame of 1.36 GPa and would fail outright below 0.14.'),
  ('rockphysics', 'intermediate', 'module', 'm03-substituting-the-fluid', 8, 'Why does the shear velocity rise when brine is replaced by gas?', '["A fixed shear modulus divided by a smaller density.", "The gas stiffens the grain contacts as it dries the rock.", "The shear modulus rises slightly with the fluid change.", "The frequency of the shear wave increases with lower density."]'::jsonb, 0, '$v_s = \sqrt{\mu/\rho}$ with $\mu$ fixed at 7.29 GPa and $\rho$ falling from 2250 to 2038.71, giving 1890.9758806113214 m/s. A higher shear velocity in a gas sand is a density observation.'),
  ('rockphysics', 'intermediate', 'module', 'm03-substituting-the-fluid', 9, 'How much Gassmann arithmetic is needed to get the substituted shear velocity?', '["The forward relation only.", "None at all, on either side.", "Both the forward and inverse relations.", "The inverse relation only."]'::jsonb, 1, 'It is the log''s own shear modulus over the substituted density, and both come from elsewhere. The whole of Gassmann''s relation is spent on the compressional velocity.'),
  ('rockphysics', 'intermediate', 'module', 'm03-substituting-the-fluid', 10, 'By how much does the Ekene acoustic impedance fall on gas substitution?', '["9.4 percent, matching the density fall.", "9.2 percent, matching the velocity fall.", "17.72 percent, from 7.200e6 to 5.923875e6.", "27.1 percent, the sum of the velocity and density falls."]'::jsonb, 2, 'Impedance is the product, so a 9.2 percent velocity fall and a 9.4 percent density fall compound to 17.7 percent rather than adding to 18.6.'),
  ('rockphysics', 'intermediate', 'module', 'm03-substituting-the-fluid', 11, 'Which contributes more to the Ekene impedance drop, the velocity or the density?', '["They contribute exactly equally by construction.", "The velocity, by about a factor of two.", "The velocity, marginally.", "The density, marginally so."]'::jsonb, 3, 'Velocity alone would give a 9.2 percent fall and density alone 9.4 percent. Half of a gas anomaly''s impedance signature is bookkeeping about what the pores weigh.'),
  ('rockphysics', 'intermediate', 'module', 'm03-substituting-the-fluid', 12, 'What happens to the Ekene velocity ratio on gas substitution?', '["It falls from 1.7777777777777777 to 1.5366125278606173.", "It rises from 1.7777777777777777 to 1.8901234567901234.", "It stays at 1.7777777777777777, since both velocities scale together.", "It falls from 1.968 to 1.537, matching the shale value."]'::jsonb, 0, 'The two velocities move in opposite directions, so the ratio falls by 13.6 percent, which is more than either velocity moved. The brine value is exactly 16/9, an artefact of a fixture built on round numbers.'),
  ('rockphysics', 'intermediate', 'module', 'm03-substituting-the-fluid', 13, 'Why is the velocity ratio a better fluid discriminator than either velocity alone?', '["It is measured more precisely than either velocity.", "Porosity and lithology move it far less than gas does.", "It removes the dependence on the density log.", "It is dimensionless, so it needs no calibration."]'::jsonb, 1, 'A porosity increase lowers both velocities in similar proportion and barely moves the ratio; more clay raises it; gas lowers it sharply. That is why impedance against velocity ratio is the standard working crossplot.'),
  ('rockphysics', 'intermediate', 'module', 'm03-substituting-the-fluid', 14, 'Where does an oil substitution land relative to brine and gas at Ekene?', '["Roughly halfway, at 3053 m/s.", "At 3008.4 m/s, about one third of the way to the gas case.", "At 3008.4 m/s, about two thirds of the way to the gas case.", "Closer to gas than to brine, at 2950 m/s."]'::jsonb, 2, 'Brine 3200, oil 3008.378760376558, gas 2905.6972280296195. The drop to oil is 191.6 m/s and the further drop to gas only 102.7, so oil and gas are the hard pair to tell apart.'),
  ('rockphysics', 'intermediate', 'module', 'm03-substituting-the-fluid', 15, 'Why can an amplitude not distinguish an oil case from a gas case at Ekene?', '["The two cases have the same density after substitution.", "They differ by less than 1 percent in impedance.", "Oil and gas have the same bulk modulus at these conditions.", "They differ by 10 percent in impedance, less than the porosity uncertainty is worth."]'::jsonb, 3, 'A porosity range of plus or minus 0.05 moves the predicted velocity by over 300 m/s, three times the 103 m/s that separates oil from gas. The amplitude can still separate either from brine.'),
  ('rockphysics', 'intermediate', 'module', 'm04-the-gas-effect', 1, 'What does one percent of gas do to the Ekene velocity?', '["Drops it to 3078.87 m/s, about a third of the drop.", "Drops it to 3190 m/s, roughly one percent of the way.", "Drops it to 2915.26 m/s, three quarters of the drop.", "Nothing measurable, since one percent is below detection."]'::jsonb, 0, '32.76 percent of the 369.72080941195463 m/s available. Five percent of gas delivers 77.01 percent, which is why seismic amplitude cannot count gas.'),
  ('rockphysics', 'intermediate', 'module', 'm04-the-gas-effect', 2, 'Why does so little gas do so much?', '["Gassmann''s relation is non-linear in the fluid modulus.", "Wood''s equation adds compliances, not stiffnesses.", "Gas displaces brine from the largest pores first.", "The gas dissolves in the brine and softens it further."]'::jsonb, 1, '$1/K_{mix} = S_w/K_{brine} + (1-S_w)/K_{gas}$, and gas is 48 times more compliant, so at one percent it already contributes a third of the mixture''s compliance.'),
  ('rockphysics', 'intermediate', 'module', 'm04-the-gas-effect', 3, 'At what water saturation is the Ekene velocity lowest?', '["0.80, at 2833.1800 m/s.", "0.00, at 2905.6972280296195 m/s.", "0.73, at 2830.2791905880454 m/s.", "0.50, at 2844.3861 m/s."]'::jsonb, 2, 'The slowest rock holds 27 percent gas, and pure gas is 75.42 m/s faster than that. The velocity is not monotonic in saturation.'),
  ('rockphysics', 'intermediate', 'module', 'm04-the-gas-effect', 4, 'Why does the velocity turn back up beyond the minimum?', '["The density keeps falling after the modulus has collapsed.", "The gas begins to stiffen the frame at high saturation.", "Wood''s equation reverses above 50 percent gas.", "The shear modulus rises to compensate."]'::jsonb, 0, 'The numerator effect is governed by Wood mixing and finishes within a few percent; the denominator effect is linear in gas fraction and continues all the way. With nothing left to soften, the lightening wins.'),
  ('rockphysics', 'intermediate', 'module', 'm04-the-gas-effect', 5, 'What is the mixture bulk modulus at Sw 0.73 compared with pure gas?', '["195.45 MPa against 2697.81 MPa, a factor of fourteen.", "195.45 MPa against 55.72 MPa, both tiny against the frame.", "55.72 MPa in both cases, since the fluid is already gas dominated.", "2697.81 MPa against 195.45 MPa, since brine still dominates."]'::jsonb, 1, 'Both are small against the frame''s 7350 MPa, which is why the two cases have nearly the same saturated modulus and the turn between them is a density effect.'),
  ('rockphysics', 'intermediate', 'module', 'm04-the-gas-effect', 6, 'Two velocities of 2870 m/s are read from the Ekene curve. What saturations do they correspond to?', '["About 0.99 and about 0.95, both near the cliff.", "A single saturation near 0.5, since the curve is monotonic.", "About 0.85 and about 0.15, either side of the minimum.", "None. That velocity lies below the curve''s minimum."]'::jsonb, 2, 'The minimum at Sw 0.73 makes the curve double valued, so no amount of processing separates the two. The reservoir volumes implied by the two ends differ by a factor of ten.'),
  ('rockphysics', 'intermediate', 'module', 'm04-the-gas-effect', 7, 'What separates a five percent gas saturation from a full gas column in velocity?', '["Nothing at all, since both are on the flat floor.", "294 m/s, the full gas effect.", "75 m/s, the height of the turn.", "9.6 m/s in velocity, or 0.33 percent of it."]'::jsonb, 3, '2915.2644777573832 against 2905.6972280296195. Any measurement that cannot resolve a third of a percent cannot tell the two apart, and seismic cannot.'),
  ('rockphysics', 'intermediate', 'module', 'm04-the-gas-effect', 8, 'What is fizz gas?', '["A residual saturation producing nearly the whole anomaly.", "Gas coming out of solution in the borehole during logging.", "A gas cap too thin to be resolved by the seismic wavelet.", "Gas dissolved in the formation brine at reservoir pressure."]'::jsonb, 0, 'Saturations of a few percent occur where a trap leaked, where gas exsolved near a fault, or where a small charge arrived. All look much like a full column on amplitude alone.'),
  ('rockphysics', 'intermediate', 'module', 'm04-the-gas-effect', 9, 'How does impedance behave compared with velocity as gas is added?', '["It saturates faster than velocity, since it is a product.", "It keeps falling once the velocity has stopped.", "It behaves identically, since it is proportional to velocity.", "It rises after the minimum, faster than velocity does."]'::jsonb, 1, 'At five percent gas the impedance is 6,528,547 and at full gas 5,923,875, a separation of 9.26 percent against 0.33 percent in velocity. Slightly better, and still not enough.'),
  ('rockphysics', 'intermediate', 'module', 'm04-the-gas-effect', 10, 'Which observation is the strongest evidence of a genuine hydrocarbon column rather than residual gas?', '["A large negative intercept on the near offsets.", "A bright amplitude conforming to the mapped closure.", "A flat spot, which reflects from the contact.", "A low velocity ratio measured from the gather."]'::jsonb, 2, 'Residual gas does not produce a contact reflection. Conformance to structure is good supporting evidence and the other two are consistent with a few percent of gas.'),
  ('rockphysics', 'intermediate', 'module', 'm04-the-gas-effect', 11, 'What should a rock physics study conclude about saturation from an amplitude?', '["That it equals the modelled full gas case if the amplitudes match.", "That it can be inverted given a good porosity estimate.", "That it is above 50 percent if the anomaly is bright.", "That it cannot be determined, and should be carried as a range."]'::jsonb, 3, 'Reaching that conclusion about itself is a legitimate and useful deliverable, because a predicted saturation from amplitude is not a real quantity.'),
  ('rockphysics', 'intermediate', 'module', 'm04-the-gas-effect', 12, 'Which chain of inference does this module break?', '["Bright amplitude, therefore charged, therefore a known volume.", "Bright amplitude, therefore soft rock, therefore high porosity.", "Low velocity ratio, therefore gas, therefore commercial.", "Flat spot, therefore a contact, therefore a column."]'::jsonb, 0, 'The step from charged to a known volume fails, because the amplitude saturates within a few percent of gas. The step to charged is itself weaker than it looks, since porosity can also soften a rock.'),
  ('rockphysics', 'intermediate', 'module', 'm04-the-gas-effect', 13, 'Which error is more expensive in a mature basin?', '["Over-reading a bright anomaly as a saturation measurement.", "Dismissing a dim prospect whose rock is not sensitive.", "Modelling the gas case at the wrong reservoir conditions.", "Confusing the dry frame with the mineral frame."]'::jsonb, 1, 'The obvious bright prospects are drilled first, so what remains is rock that does not shout. The Biot coefficient tells you which regime you are in: at 0.80 the Ekene sand is fluid sensitive and a tight rock at 0.4 would not be.'),
  ('rockphysics', 'intermediate', 'module', 'm04-the-gas-effect', 14, 'What is the honest statement about the Ekene amplitude?', '["Consistent with an oil sand, since oil and gas cannot be separated.", "Consistent with a gas sand at the modelled saturation of 100 percent.", "Consistent with a gas sand and with a few percent of residual gas alone.", "Inconclusive, since the porosity uncertainty exceeds the whole anomaly."]'::jsonb, 2, 'The modelling cannot distinguish those cases, and the distinction should be made from conformance to structure, a flat spot, or pressure data. The porosity uncertainty exceeds the oil to gas separation but not the whole anomaly.'),
  ('rockphysics', 'intermediate', 'module', 'm04-the-gas-effect', 15, 'What is the full velocity drop available at Ekene, and to where?', '["75.42 m/s, from the minimum up to the pure gas case.", "294.30 m/s, from 3200 down to the pure gas case.", "191.62 m/s, from 3200 down to the oil case.", "369.72 m/s, down to the minimum at Sw 0.73."]'::jsonb, 3, 'The drop to pure gas is 294.30 m/s and the drop to the minimum is larger, because the curve dips below the pure gas value before turning back up.'),
  ('rockphysics', 'intermediate', 'module', 'm05-when-there-is-no-shear-log', 1, 'Why do many wells have no shear log?', '["Monopole sonic tools record no usable shear in slow formations.", "Shear logs are only run when a rock physics study is planned.", "The shear arrival is always present but is usually discarded in processing.", "Shear velocity cannot be measured in a fluid filled borehole at all."]'::jsonb, 0, 'A monopole tool needs the shear velocity to exceed the mud velocity, which fails in most shallow sands and nearly all shales. Dipole tools record it and are a more recent standard.'),
  ('rockphysics', 'intermediate', 'module', 'm05-when-there-is-no-shear-log', 2, 'What can be computed from a compressional velocity and a density with no shear log?', '["The shear modulus, from the compressional velocity alone.", "Acoustic impedance and the quantity $K + \\tfrac{4}{3}\\mu$.", "The saturated bulk modulus, once the porosity is known.", "Nothing useful, since both moduli need a shear measurement."]'::jsonb, 1, 'One measured quantity, two unknown moduli. Separating them needs a second measurement, which is exactly what the shear log would have supplied.'),
  ('rockphysics', 'intermediate', 'module', 'm05-when-there-is-no-shear-log', 3, 'What is the Castagna mudrock line?', '["A quadratic fit to brine saturated limestones and dolomites.", "$v_s = 0.80416 v_p - 855.88$, fitted to sandstones alone.", "$v_s = 0.8621 v_p - 1172.4$, fitted to brine saturated clastics.", "The line of constant Poisson''s ratio through the origin."]'::jsonb, 2, 'At 3000 m/s it gives 1413.8999999999996 m/s. Both qualifiers matter: brine saturated means not hydrocarbon bearing, and clastic means not carbonate.'),
  ('rockphysics', 'intermediate', 'module', 'm05-when-there-is-no-shear-log', 4, 'What does the mudrock line''s negative intercept tell you?', '["It has no physical content at its low velocity end.", "It was fitted with an offset to match carbonate data.", "It predicts a fluid rather than a rock above 1360 m/s.", "It should be forced through the origin before use."]'::jsonb, 0, 'At 1360 m/s it predicts zero shear velocity and below that a negative one. It is a summary of a dataset within a range rather than a statement about rock.'),
  ('rockphysics', 'intermediate', 'module', 'm05-when-there-is-no-shear-log', 5, 'How far is the Ekene sand from the mudrock line?', '["107.30 m/s above it, matching the Greenberg-Castagna gap.", "213.68 m/s above it, or 13.5 percent.", "It sits exactly on it, which is why the fixture uses it.", "120.05 m/s below it, matching the estimator error."]'::jsonb, 1, 'The line predicts 1586.32 m/s at 3200 and the well measured 1800. A rock above the line is stiffer in shear than a typical brine clastic, which suits a clean quartz rich sand.'),
  ('rockphysics', 'intermediate', 'module', 'm05-when-there-is-no-shear-log', 6, 'How does Greenberg-Castagna differ from the mudrock line?', '["It works on hydrocarbon bearing rocks as well as brine ones.", "It uses a quadratic instead of a straight line for all lithologies.", "It fits a separate curve per lithology and then mixes them.", "It predicts compressional velocity from shear rather than the reverse."]'::jsonb, 2, 'Three of its four lithology curves are straight lines and only limestone carries a quadratic term. The mixing of the per lithology estimates is the unusual part.'),
  ('rockphysics', 'intermediate', 'module', 'm05-when-there-is-no-shear-log', 7, 'What is the Greenberg-Castagna mixing rule?', '["The geometric mean of the two extreme lithology estimates.", "The volume weighted arithmetic mean of the estimates.", "The harmonic mean of the estimates, weighted by volume.", "The mean of the arithmetic and harmonic means of the estimates."]'::jsonb, 3, 'It is the Voigt Reuss Hill idea applied to velocities. At Ekene the arithmetic mean is 1522.136 and the harmonic 1520.2585531342977, and their average is the graded 1521.197276567149.'),
  ('rockphysics', 'intermediate', 'module', 'm05-when-there-is-no-shear-log', 8, 'Why are the two means so close at Ekene?', '["The sand and shale estimates differ by only 115 m/s.", "The mixture is nearly all sandstone at 70 percent.", "The harmonic mean always approaches the arithmetic one above 1000 m/s.", "Both are computed from the same quadratic coefficients."]'::jsonb, 0, '1556.6 against 1441.72 at 3000 m/s, so the bounds are tight and the choice of mixing rule barely matters. A mixture with a genuinely soft component would have a wider spread.'),
  ('rockphysics', 'intermediate', 'module', 'm05-when-there-is-no-shear-log', 9, 'How much does using the mudrock line instead of Greenberg-Castagna cost at 3000 m/s?', '["213.68 m/s, or about 13 percent.", "107.30 m/s, or about 7 percent.", "11.6 m/s, the same as a ten percent lithology error.", "Nothing, since the two agree within their own uncertainty."]'::jsonb, 1, '1521.197276567149 against 1413.8999999999996. Choosing a lithology aware method matters about ten times more than getting the lithology split exactly right, which is worth 11.6 m/s.'),
  ('rockphysics', 'intermediate', 'module', 'm05-when-there-is-no-shear-log', 10, 'What does Greenberg-Castagna predict at the Ekene sand''s logged velocity?', '["1521.197276567149 m/s, the graded capstone value.", "1800 m/s, matching the measurement exactly.", "1679.9458454651794 m/s, against a measured 1800.", "1586.32 m/s, the mudrock line value."]'::jsonb, 2, 'The estimator under-predicts by 120.05415453482057 m/s, which is 6.7 percent, because this sand sits at the stiff edge of the population the regression was fitted through.'),
  ('rockphysics', 'intermediate', 'module', 'm05-when-there-is-no-shear-log', 11, 'What does that test tell you about the graded value at 3000 m/s?', '["Nothing, since the two velocities describe different rocks.", "It is wrong and should be corrected before submitting.", "It is more accurate than the value at 3200, being nearer the fit centre.", "It is the correct output of the method, not the rock''s shear velocity."]'::jsonb, 3, 'The capstone asks what the method gives. If the same 6.7 percent bias applies, the rock''s true shear velocity at 3000 m/s would be nearer 1630 m/s.'),
  ('rockphysics', 'intermediate', 'module', 'm05-when-there-is-no-shear-log', 12, 'How is an estimator calibrated with one well that has both logs?', '["Form the ratio of measured to estimated and carry it to the other wells.", "Refit the regression coefficients to that well''s data.", "Use the well''s shear log directly in place of every estimate.", "Average the estimator''s output with the measurement everywhere."]'::jsonb, 0, 'At Ekene the ratio is 1.0714631098727931, and applying it to the 3000 m/s estimate gives 1629.906764680661. It assumes the lithology and cementation match, which should be stated.'),
  ('rockphysics', 'intermediate', 'module', 'm05-when-there-is-no-shear-log', 13, 'What does a 6.7 percent shear velocity error do to the saturated bulk modulus?', '["Leaves it unchanged, since the bulk modulus is fluid blind.", "Moves it 9.41 percent, to 14.573 GPa from 13.32.", "Moves it 6.7 percent, in proportion to the velocity error.", "Moves it 13.4 percent, twice the velocity error."]'::jsonb, 1, 'The shear modulus falls 12.9 percent to 6.349990598315363 GPa, and since it is subtracted from $\rho v_p^2$ the bulk modulus moves the other way and by a comparable absolute amount.'),
  ('rockphysics', 'intermediate', 'module', 'm05-when-there-is-no-shear-log', 14, 'In what order must shear estimation and fluid substitution be done?', '["Either order, since the two are independent.", "Substitute first, then estimate on the result.", "Estimate on the brine case first, then substitute.", "Estimate, substitute, then re-estimate on the substituted rock."]'::jsonb, 2, 'The empirical estimators were fitted to brine saturated rocks, and a rock that already holds hydrocarbon does not lie on that trend.'),
  ('rockphysics', 'intermediate', 'module', 'm05-when-there-is-no-shear-log', 15, 'What does Greenberg-Castagna give if applied to the Ekene gas case velocity?', '["An error, since the estimator refuses hydrocarbon bearing input.", "1890.9758806113214 m/s, since the estimator is fluid blind.", "1679.9458454651794 m/s, the same as at the logged velocity.", "1446.343832922053 m/s against a true 1890.98, out by 23.5 percent."]'::jsonb, 3, 'Nothing has gone wrong with the estimator: it has correctly answered what a brine rock at 2905.70 m/s would have for a shear velocity. The rock in question is not a brine rock.'),
  ('rockphysics', 'intermediate', 'module', 'm06-the-substitution-workflow', 1, 'What is the first step of the substitution workflow?', '["Establishing which fluid was in the pores when the log was recorded.", "Converting the logged velocities and density into moduli.", "Fixing the porosity and the mineral modulus.", "Computing the fluid properties at in situ conditions."]'::jsonb, 0, 'Everything downstream assumes it, and a substitution run on a hydrocarbon bearing interval treated as brine is wrong from the first line and produces no error.'),
  ('rockphysics', 'intermediate', 'module', 'm06-the-substitution-workflow', 2, 'Which workflow step is exact in both directions?', '["Recovering the dry frame with inverse Gassmann.", "Converting between velocities and moduli.", "Computing the fluid properties from conditions.", "Substituting the new fluid with the forward relation."]'::jsonb, 1, '$\mu = \rho v_s^2$ and $K = \rho v_p^2 - \tfrac{4}{3}\mu$ invert without loss, so any error in a substitution comes from the substitution itself.'),
  ('rockphysics', 'intermediate', 'module', 'm06-the-substitution-workflow', 3, 'Which step carries the most leverage?', '["Computing the fluid properties, which the substitution depends on.", "Recovering the dry frame, which is the tier''s central calculation.", "Fixing the porosity, which is worth five times the mineral modulus.", "Converting back to velocities, which is what the answer is read from."]'::jsonb, 2, 'A porosity wrong by 0.05 moves the answer by more than the entire oil to gas separation, and it is an assumption rather than a measurement.'),
  ('rockphysics', 'intermediate', 'module', 'm06-the-substitution-workflow', 4, 'Why can the order of shear estimation and substitution not be swapped?', '["The estimators were fitted to brine saturated rocks.", "The substitution needs a shear modulus, which the estimate supplies.", "The estimate depends on the substituted density.", "Gassmann requires the shear velocity to be measured rather than estimated."]'::jsonb, 0, 'A rock that already holds hydrocarbon does not lie on the brine trend, so estimating from its compressional velocity gives an answer 23.5 percent low at Ekene.'),
  ('rockphysics', 'intermediate', 'module', 'm06-the-substitution-workflow', 5, 'Which check tests the whole chain at once?', '["The grain density, computed from the log and the porosity.", "The round trip, substituting the original fluid back.", "The Biot coefficient, computed from the two moduli.", "The direction checks on the four quantities that move."]'::jsonb, 1, 'It exercises the conversion into moduli, both Gassmann directions, the density bookkeeping and the conversion back. At Ekene it returns 3200.0000, 1800.0000 and 2250.0000 exactly.'),
  ('rockphysics', 'intermediate', 'module', 'm06-the-substitution-workflow', 6, 'What does the round trip check not test?', '["Whether the density bookkeeping is right.", "Whether the forward relation is implemented correctly.", "Whether the assumed porosity is correct.", "Whether the conversion into moduli is right."]'::jsonb, 2, 'It passes at every porosity, because it tests internal consistency rather than the correctness of an assumption. The grain density check is the one that tests the porosity.'),
  ('rockphysics', 'intermediate', 'module', 'm06-the-substitution-workflow', 7, 'What is the implied grain density of the Ekene sand?', '["2038.7 kg/m3, which is the gas case bulk density.", "2250 kg/m3, which is the logged bulk density.", "2629 kg/m3, which is the Associate tier''s mineral frame density.", "2660.7 kg/m3, consistent with a 70/30 quartz and clay mix."]'::jsonb, 3, '$(2250 - 0.25 \times 1017.8249875)/0.75$. Quartz is 2650 and clays run from about 2550 to 2800, so 2661 is entirely consistent.'),
  ('rockphysics', 'intermediate', 'module', 'm06-the-substitution-workflow', 8, 'Which pair of failures passes every quality control check in this tier?', '["A wrong fluid state, and a violated Gassmann assumption.", "A wrong porosity, and a transposed pair of fluids.", "A wrong mineral modulus, and an uncalibrated shear estimate.", "A negative dry frame, and a frame above the mineral modulus."]'::jsonb, 0, 'Both are established outside the substitution, from petrophysics and geology, which is the honest limit of what a rock physics quality control can do. The last pair is caught by the guards.'),
  ('rockphysics', 'intermediate', 'module', 'm06-the-substitution-workflow', 9, 'Which four directions should a brine to gas substitution produce?', '["All four down, since gas softens and lightens the rock.", "Bulk modulus down, density down, compressional down, shear up.", "Bulk modulus down, density down, both velocities down.", "Bulk modulus up, density down, compressional down, shear up."]'::jsonb, 1, 'Any of the four going the other way means the two fluids have been swapped somewhere. The shear velocity rising is the one that surprises people.'),
  ('rockphysics', 'intermediate', 'module', 'm06-the-substitution-workflow', 10, 'What are the capstone settings for this tier?', '["Saturation 0.00, porosity 0.20, mineral modulus 35 GPa.", "Saturation 0.80, porosity 0.25, mineral modulus 37 GPa.", "Saturation 0.00, porosity 0.25, mineral modulus 37 GPa.", "Saturation 0.73, porosity 0.25, mineral modulus 37 GPa."]'::jsonb, 2, 'That is the panel''s default configuration. Sw 0.80 is the Associate tier''s Wood mixture and Sw 0.73 is the velocity minimum, neither of which the capstone books.'),
  ('rockphysics', 'intermediate', 'module', 'm06-the-substitution-workflow', 11, 'Which two capstone values need no panel at all?', '["The saturated bulk modulus and the dry frame modulus.", "The dry frame modulus and the gas case density.", "The gas case velocity and the Greenberg-Castagna estimate.", "The shear modulus and the saturated bulk modulus."]'::jsonb, 3, '7.29 and 13.32 GPa follow from the log by two exact lines of arithmetic. The gas case density is also hand reachable, but through the fluid densities rather than the log alone.'),
  ('rockphysics', 'intermediate', 'module', 'm06-the-substitution-workflow', 12, 'At what velocity is the capstone''s Greenberg-Castagna estimate asked for?', '["3000 m/s, which is not the logged velocity.", "3200 m/s, the sand''s logged compressional velocity.", "2905.6972280296195 m/s, the gas case velocity.", "2743 m/s, the overlying shale''s velocity."]'::jsonb, 0, 'Running it at the logged 3200 gives 1679.9458454651794, which fails the 1 m/s tolerance by 158.7 m/s. It is the most common error on this capstone.'),
  ('rockphysics', 'intermediate', 'module', 'm06-the-substitution-workflow', 13, 'Which capstone value is most sensitive to a wrong porosity?', '["The shear modulus, which is computed from the log.", "The dry frame modulus, which runs 5.356 to 8.546 GPa over 0.20 to 0.30.", "The Greenberg-Castagna estimate, which depends on the lithology.", "The saturated bulk modulus, which is exact from the log."]'::jsonb, 1, 'Both the shear modulus and the saturated bulk modulus come from the log alone and no assumption can move them, which is why they are graded to 0.01.'),
  ('rockphysics', 'intermediate', 'module', 'm06-the-substitution-workflow', 14, 'What does the Expert tier add to this one?', '["A saturation height model replacing the constant water saturation.", "A property model letting porosity vary across the field.", "A shale above the sand, and the reflection between them.", "A probabilistic treatment of the porosity uncertainty."]'::jsonb, 2, 'Two isolated rocks become two interfaces, and the fluid substitution flips the AVO class from I to III. The other three are real next steps and none of them is that tier.'),
  ('rockphysics', 'intermediate', 'module', 'm06-the-substitution-workflow', 15, 'Which result from this tier most affects the Expert tier''s gradient?', '["The Biot coefficient of 0.80.", "The dry frame modulus recovered by inverse Gassmann.", "The gas case density from the bookkeeping.", "The shear velocity, measured or estimated."]'::jsonb, 3, 'The AVO gradient is dominated by the shear contrast, so an uncalibrated shear estimate can change the predicted class. The density drives the intercept instead.'),
  ('rockphysics', 'intermediate', 'final', null, 1, 'Which set of six values is the Ekene substitution capstone answer key?', '["7.29, 13.32, 7.350343061720982, 2905.6972280296195, 2038.7104517793223, 1521.197276567149.", "7.29, 13.32, 30.87940062475596, 2905.6972280296195, 2038.7104517793223, 1521.197276567149.", "7.29, 13.32, 7.350343061720982, 3200, 2250, 1800.", "13.32, 7.29, 7.492988063073051, 2905.6972280296195, 2038.7104517793223, 1679.9458454651794."]'::jsonb, 0, 'The set with 30.879 substitutes the mineral frame for the dry frame; the set ending 3200, 2250, 1800 is the logged brine case; the last set gives the gas case saturated modulus and the estimator run at the wrong velocity.'),
  ('rockphysics', 'intermediate', 'final', null, 2, 'What single input changes between the Associate booking and this tier''s?', '["The conditions at which the fluids are computed.", "The ingredients go into a rock with porosity.", "The mineral mixing rule used for the frame.", "The saturation at which the pore fluid is mixed."]'::jsonb, 1, 'The conditions, the fluid properties and the mineral frame are all reused unchanged from the tier below. What is new is a logged rock to put them into.'),
  ('rockphysics', 'intermediate', 'final', null, 3, 'Compute the shear modulus of a rock at 2250 kg/m3 and 1800 m/s.', '["7.29 GPa exactly.", "4.05 GPa.", "13.32 GPa exactly.", "3.24 GPa."]'::jsonb, 0, '$2250 \times 1800^2 = 7.29 \times 10^9$ Pa, with no rounding at any step. The value 13.32 GPa is the saturated bulk modulus of the same rock.'),
  ('rockphysics', 'intermediate', 'final', null, 4, 'How is the saturated bulk modulus obtained from a log?', '["$\\rho v_p^2$ on its own.", "$\\rho v_p^2 - \\tfrac{4}{3}\\mu$.", "$\\rho v_p^2 + \\tfrac{4}{3}\\mu$.", "$\\rho(v_p^2 - v_s^2)$."]'::jsonb, 1, 'At Ekene that is $23.04 - 9.72 = 13.32$ GPa. Forgetting to remove the shear term leaves 23.04, which is the quantity a well with no shear log can reach.'),
  ('rockphysics', 'intermediate', 'final', null, 5, 'What is the Ekene dry frame bulk modulus?', '["13.32 GPa.", "30.87940062475596 GPa.", "7.350343061720982 GPa.", "7.492988063073051 GPa."]'::jsonb, 2, 'The 30.879 value is the mineral frame from the tier below, 13.32 is the logged saturated modulus, and 7.493 is the gas case saturated modulus.'),
  ('rockphysics', 'intermediate', 'final', null, 6, 'How much of the Ekene saturated bulk modulus does the brine supply?', '["4.8 percent, since fluids are soft.", "80 percent, matching the Biot coefficient.", "25 percent, matching the porosity.", "44.8 percent, or 5.9697 GPa."]'::jsonb, 3, 'If the fluid contributed only a few percent there would be no such thing as a direct hydrocarbon indicator. It contributes nearly half, which is why fluid changes show up on seismic.'),
  ('rockphysics', 'intermediate', 'final', null, 7, 'Why is the dry frame far softer than the mineral frame?', '["Grains touch only at contacts, which carry the load.", "The dry frame is computed at reservoir pressure and the mineral frame at surface.", "The Voigt Reuss Hill average is an upper bound rather than an estimate.", "The dry frame still contains irreducible water."]'::jsonb, 0, '7.350343061720982 against 30.87940062475596 GPa. Porosity removes material and the contacts, not the grain interiors, control the frame stiffness.'),
  ('rockphysics', 'intermediate', 'final', null, 8, 'What is the Ekene Biot coefficient and what does it say?', '["0.20, since the frame is nearly as stiff as its mineral.", "0.80, so the frame is compliant and the rock is fluid sensitive.", "0.55, the ratio of dry to saturated modulus.", "0.25, equal to the porosity."]'::jsonb, 1, '$1 - 7.350343061720982/37$. A value near 1 means most of the fluid''s stiffness is transmitted, and a tight cemented rock at 0.4 would show a much weaker fluid effect.'),
  ('rockphysics', 'intermediate', 'final', null, 9, 'Why can a fluid not change the shear modulus?', '["Shear waves do not enter the pore space at all.", "Its shear modulus is small compared with the frame''s.", "A fluid at rest has no restoring force against a change of shape.", "Gassmann''s relation neglects the fluid''s shear stiffness."]'::jsonb, 2, 'The value is exactly zero rather than small, so $\mu_{sat} = \mu_{dry}$ is exact within Gassmann''s assumptions rather than an approximation.'),
  ('rockphysics', 'intermediate', 'final', null, 10, 'What is the Ekene gas case shear velocity?', '["1709.02 m/s, below the logged value.", "1800 m/s, unchanged by the substitution.", "1846.2 m/s, since only part of the density change reaches the shear velocity.", "1890.9758806113214 m/s, higher than the logged 1800."]'::jsonb, 3, '$\sqrt{7.29 \times 10^9 / 2038.7104517793223}$. The modulus is fixed and the density fell, so the velocity must rise.'),
  ('rockphysics', 'intermediate', 'final', null, 11, 'How much Gassmann arithmetic does the substituted shear velocity need?', '["None at all.", "The forward relation only.", "The inverse relation only.", "Both, since the shear modulus is recomputed."]'::jsonb, 0, 'The whole of Gassmann''s relation is spent on the compressional velocity. The shear velocity follows from a quantity that did not change and a density that is bookkeeping.'),
  ('rockphysics', 'intermediate', 'final', null, 12, 'How is the substituted density computed?', '["From the forward Gassmann relation alongside the modulus.", "$\\rho + \\phi(\\rho_{fl}'' - \\rho_{fl})$, which is mass bookkeeping.", "By scaling the logged density by the fluid modulus ratio.", "From the substituted velocities and the shear modulus."]'::jsonb, 1, '$2250 + 0.25(172.66679461728904 - 1017.8249875) = 2038.7104517793223$. It involves none of Gassmann''s assumptions, which is why it is the robust half of the answer.'),
  ('rockphysics', 'intermediate', 'final', null, 13, 'What does the grain density check test, and what does it give at Ekene?', '["The fluid density, and it gives 1017.8 kg/m3.", "The mineral modulus, and it gives 2629 kg/m3.", "The porosity, and it gives 2660.7 kg/m3.", "The dry frame, and it gives 2250 kg/m3."]'::jsonb, 2, '$(\rho - \phi\rho_{fl})/(1-\phi)$, consistent with a 70/30 quartz and clay mixture. The value 2629 is the Associate tier''s mineral frame density, which is a different quantity.'),
  ('rockphysics', 'intermediate', 'final', null, 14, 'A 2250 kg/m3 sand assumed at 0.15 porosity gives what grain density?', '["2661 kg/m3, unchanged from the 0.25 case.", "2661 kg/m3, which is quartz to within logging accuracy.", "2849 kg/m3, high but possible.", "2467 kg/m3, below every common clastic mineral."]'::jsonb, 3, 'The porosity is rejected on density grounds alone. That same porosity would give a dry frame of 1.36 GPa, and below 0.14 the calculation refuses outright.'),
  ('rockphysics', 'intermediate', 'final', null, 15, 'What is the Ekene impedance drop on gas substitution?', '["17.72 percent, from 7.200e6 to 5.923875e6.", "9.2 percent, matching the velocity fall alone.", "9.4 percent, matching the density fall alone.", "13.6 percent, matching the velocity ratio fall."]'::jsonb, 0, 'Impedance is the product of the two, so a 9.2 percent velocity fall and a 9.4 percent density fall compound rather than add.'),
  ('rockphysics', 'intermediate', 'final', null, 16, 'Which contributes more to that drop?', '["The velocity, by a factor of two.", "The density, marginally.", "The velocity, marginally.", "Neither. They are equal by construction."]'::jsonb, 1, 'Velocity alone gives 6,537,819 and density alone 6,523,873, against 7,200,000. Half of a gas anomaly''s impedance signature is bookkeeping about what the pores weigh.'),
  ('rockphysics', 'intermediate', 'final', null, 17, 'What happens to the Ekene velocity ratio on substitution?', '["It is unchanged, since both velocities scale together.", "It rises, since the shear velocity rises.", "It falls from 1.7777777777777777 to 1.5366125278606173.", "It falls from 1.968 to 1.778."]'::jsonb, 2, 'The two velocities move in opposite directions so the ratio falls 13.6 percent, more than either velocity moved. The value 1.968 is the overlying shale''s.'),
  ('rockphysics', 'intermediate', 'final', null, 18, 'Why is the velocity ratio a better fluid discriminator than either velocity?', '["It needs no density log to compute.", "It has a smaller measurement uncertainty.", "Both velocities come from the same tool, so the ratio cancels what they share.", "Porosity and lithology move it much less than gas does."]'::jsonb, 3, 'A porosity increase lowers both velocities in proportion and barely moves the ratio, more clay raises it, and gas lowers it sharply. That is why the standard crossplot is impedance against ratio.'),
  ('rockphysics', 'intermediate', 'final', null, 19, 'Where does an oil substitution land at Ekene?', '["3008.378760376558 m/s, two thirds of the way.", "2905.6972280296195 m/s, the same as gas.", "3100 m/s, one third of the way to gas.", "3008.378760376558 m/s, one third of the way to gas."]'::jsonb, 0, 'The drop from brine to oil is 191.62 m/s and the further drop to gas only 102.68, which is why oil and gas are the hard pair to distinguish.'),
  ('rockphysics', 'intermediate', 'final', null, 20, 'Why can an amplitude not separate oil from gas at Ekene?', '["Oil and gas have the same density once substituted.", "They differ by 10 percent in impedance, less than the porosity uncertainty.", "Gassmann returns the same saturated modulus for both, since both are hydrocarbons.", "Their bulk moduli are within one percent of each other."]'::jsonb, 1, 'A porosity range of plus or minus 0.05 moves the predicted velocity by over 300 m/s, three times the 103 m/s oil to gas separation. Either can still be separated from brine.'),
  ('rockphysics', 'intermediate', 'final', null, 21, 'What does one percent of gas do to the Ekene velocity?', '["Takes it to 3190 m/s, roughly one percent down.", "Takes it to 3078.87 m/s, which is a tenth of the available drop.", "Takes it to 3078.87 m/s, a third of the available drop.", "Nothing detectable, since it is below the noise."]'::jsonb, 2, 'Five percent delivers 77.01 percent, and the full drop to the minimum is 369.72080941195463 m/s. That saturation is why amplitude cannot count gas.'),
  ('rockphysics', 'intermediate', 'final', null, 22, 'Why does so little gas do so much?', '["Gas displaces brine from the load bearing pores first.", "Gassmann''s relation is quadratic in the fluid modulus.", "One percent of gas already lowers the mixture density enough to slow the rock.", "Wood''s equation adds compliances, so the soft phase dominates."]'::jsonb, 3, '$1/K_{mix} = S_w/K_{brine} + (1-S_w)/K_{gas}$ with gas 48 times more compliant, so one percent already supplies a third of the mixture''s compliance.'),
  ('rockphysics', 'intermediate', 'final', null, 23, 'Where is the Ekene velocity minimum, and what is it?', '["Sw 0.73 at 2830.2791905880454 m/s.", "Sw 0.00 at 2905.6972280296195 m/s.", "Sw 0.50 at 2844.3861 m/s.", "Sw 0.95 at 2915.2644777573832 m/s."]'::jsonb, 0, 'The slowest rock holds 27 percent gas, and pure gas is 75.42 m/s faster. The curve is not monotonic in saturation.'),
  ('rockphysics', 'intermediate', 'final', null, 24, 'Why does the velocity turn back up before pure gas?', '["The dry frame stiffens as the last of the brine leaves the pore space.", "The density keeps falling after the fluid modulus has collapsed.", "Wood''s equation reverses above 50 percent gas.", "The shear modulus rises at high gas saturation."]'::jsonb, 1, 'The numerator effect is complete within a few percent and the denominator effect is linear in gas fraction all the way, so with nothing left to soften the lightening wins.'),
  ('rockphysics', 'intermediate', 'final', null, 25, 'What separates five percent gas from a full gas column in velocity?', '["75 m/s, the size of the turn.", "294 m/s, the full gas effect.", "9.6 m/s, or 0.33 percent.", "185 m/s, half the full drop."]'::jsonb, 2, '2915.2644777573832 against 2905.6972280296195. In impedance the separation is better, at 9.26 percent, and still not measurable against the porosity uncertainty.'),
  ('rockphysics', 'intermediate', 'final', null, 26, 'What is fizz gas and why does it matter?', '["A saturation too low to show on an amplitude map but high enough to log.", "Gas exsolving in the borehole during logging.", "A gas cap thinner than the seismic wavelet.", "A residual saturation producing nearly the full anomaly."]'::jsonb, 3, 'Residual saturations of a few percent are common and none is worth drilling, yet all look much like a full column on amplitude alone. It is a standard cause of a dry hole on a bright spot.'),
  ('rockphysics', 'intermediate', 'final', null, 27, 'Which observation best distinguishes a column from residual gas?', '["A flat spot, reflecting from the contact.", "A bright amplitude conforming to the closure.", "A strongly negative intercept at the near offsets.", "A low velocity ratio measured on the gather."]'::jsonb, 0, 'Residual gas produces no contact reflection. Conformance to structure is good supporting evidence, and the other two are consistent with a few percent of gas.'),
  ('rockphysics', 'intermediate', 'final', null, 28, 'Why do many wells lack a shear log?', '["Shear is only logged when a study requires it.", "Monopole tools record no usable shear in slow formations.", "The shear arrival is discarded during processing.", "Shear cannot be measured in a fluid filled borehole."]'::jsonb, 1, 'A monopole tool needs the shear velocity to exceed the mud velocity, which fails in most shallow sands and nearly all shales. Dipole tools record it and are more recent.'),
  ('rockphysics', 'intermediate', 'final', null, 29, 'What can be computed with a compressional velocity and a density but no shear?', '["The saturated bulk modulus, given the porosity.", "The shear modulus, from an empirical relation only.", "Impedance, and the combination $K + \\tfrac{4}{3}\\mu$.", "Neither modulus, and not the impedance either."]'::jsonb, 2, 'One measured quantity and two unknown moduli, so they cannot be separated. An estimate of the shear velocity unlocks everything, which is why the module exists.'),
  ('rockphysics', 'intermediate', 'final', null, 30, 'What does the Castagna mudrock line give at 3000 m/s?', '["1586.32 m/s.", "1521.197276567149 m/s.", "1556.6 m/s.", "1413.8999999999996 m/s."]'::jsonb, 3, '$0.8621 \times 3000 - 1172.4$. The value 1521.20 is the Greenberg-Castagna composite, 1556.6 is its sandstone curve, and 1586.32 is the mudrock line at 3200 m/s.'),
  ('rockphysics', 'intermediate', 'final', null, 31, 'What is the Greenberg-Castagna mixing rule?', '["The mean of the arithmetic and harmonic means.", "The volume weighted arithmetic mean of the estimates.", "The harmonic mean weighted by volume fraction.", "The estimate for the dominant lithology alone."]'::jsonb, 0, 'At Ekene the arithmetic mean is 1522.136 and the harmonic 1520.2585531342977, giving the graded 1521.197276567149. It is the Voigt Reuss Hill idea applied to velocities.'),
  ('rockphysics', 'intermediate', 'final', null, 32, 'How does the composite compare with the mudrock line at 3000 m/s?', '["213.68 m/s higher, or about 13 percent.", "107.29727656714931 m/s higher, or about 7 percent.", "11.6 m/s higher, the same as a lithology split error.", "Identical, since both are fitted to brine clastics."]'::jsonb, 1, 'Choosing a lithology aware method matters about ten times more than getting the split exactly right, which is worth 11.6 m/s for a ten percent change in clay volume.'),
  ('rockphysics', 'intermediate', 'final', null, 33, 'What does Greenberg-Castagna predict at the Ekene sand''s own logged velocity?', '["1890.9758806113214 m/s, which is the shear velocity of the gas case.", "1800 m/s, matching the measurement.", "1679.9458454651794 m/s, under-predicting the measured 1800.", "1556.6 m/s, the sandstone only curve at 3000 m/s."]'::jsonb, 2, 'It is 120.05415453482057 m/s low, or 6.7 percent, because this sand sits at the stiff edge of the population the regression passes through.'),
  ('rockphysics', 'intermediate', 'final', null, 34, 'What does that test say about the graded estimate at 3000 m/s?', '["It is wrong and needs correcting before submission.", "It should be replaced by this well''s own measured 1800 m/s.", "It is more reliable than the check itself, since 3000 m/s is nearer the fit centre.", "It is the method''s correct output rather than the rock''s shear velocity."]'::jsonb, 3, 'If the same 6.7 percent bias applies, the true value at 3000 m/s would be nearer 1630 m/s. Knowing whether you have a method output or a rock property is the point.'),
  ('rockphysics', 'intermediate', 'final', null, 35, 'In what order must shear estimation and substitution be done, and why?', '["Estimate on the brine case first.", "Substitute first, since the estimate needs the final density.", "Either, since the two are independent operations.", "Estimate, substitute, then re-estimate to converge."]'::jsonb, 0, 'Applying Greenberg-Castagna to the Ekene gas case velocity gives 1446.343832922053 against a true 1890.98, out by 23.5 percent, because the rock no longer lies on the brine trend.'),
  ('rockphysics', 'intermediate', 'final', null, 36, 'Which quality control check tests the whole chain at once?', '["The grain density from the log and porosity.", "The round trip back to the original fluid.", "The Biot coefficient from the two moduli.", "The four direction checks on the substitution."]'::jsonb, 1, 'It exercises both Gassmann directions, the density bookkeeping and both conversions, and at Ekene returns 3200.0000, 1800.0000 and 2250.0000 exactly.'),
  ('rockphysics', 'intermediate', 'final', null, 37, 'What does the round trip check fail to test?', '["Whether the density bookkeeping is right.", "Whether the forward relation is implemented right.", "Whether the assumed porosity is right.", "Whether the conversion to moduli is right."]'::jsonb, 2, 'It passes at every porosity, because it tests internal consistency rather than the truth of an assumption. The grain density check is the one that tests the porosity.'),
  ('rockphysics', 'intermediate', 'final', null, 38, 'Which two failures pass every check in this tier?', '["An uncalibrated shear estimate, and a transposed fluid pair.", "A wrong porosity, and a wrong mineral modulus.", "A negative dry frame, and a frame above the mineral modulus.", "A wrong fluid state, and a violated Gassmann assumption."]'::jsonb, 3, 'Both are established outside the substitution. The negative frame and the frame above the mineral modulus are exactly what the engine''s guards catch.'),
  ('rockphysics', 'intermediate', 'final', null, 39, 'At which end of the porosity range does inverse Gassmann refuse for this rock?', '["At low porosity, below about 0.14.", "At high porosity, above about 0.45.", "At both ends, outside 0.15 to 0.40.", "At neither, for any porosity between 0 and 1."]'::jsonb, 0, 'Explaining 13.32 GPa with almost no fluid needs a frame stiffer than the mineral. The frame rises with porosity and reaches only 12.0 GPa at 0.95, nowhere near 37.'),
  ('rockphysics', 'intermediate', 'final', null, 40, 'Rank these Ekene sensitivities from largest to smallest.', '["Porosity range, mineral modulus range, oil to gas separation.", "Porosity range, oil to gas separation, mineral modulus range.", "Mineral modulus range, porosity range, oil to gas separation.", "Oil to gas separation, porosity range, mineral modulus range."]'::jsonb, 1, '324 m/s for porosity 0.20 to 0.30, then 103 m/s between the oil and gas cases, then 60 m/s for 35 to 40 GPa of mineral modulus. The porosity assumption outweighs the fluid question the study is asking.'),
  ('rockphysics', 'intermediate', 'final', null, 41, 'What should always accompany a substituted velocity in a report?', '["The frequency at which Gassmann was applied.", "The mineral modulus used for the frame.", "The assumed porosity, and preferably a range.", "The shear modulus of the dry frame."]'::jsonb, 2, 'A six figure velocity with no porosity beside it is not reproducible, and the porosity is the input that moves it by more than the entire question being asked.'),
  ('rockphysics', 'intermediate', 'final', null, 42, 'What does the Expert tier add, and which result of this tier feeds it most?', '["A probabilistic treatment; the porosity range feeds the distribution.", "A property model across the field; the porosity feeds the volumes.", "A saturation height model; the density feeds the contacts.", "A shale above the sand; the shear velocity feeds the gradient."]'::jsonb, 3, 'The AVO gradient is dominated by the shear contrast, so an uncalibrated shear estimate can change the predicted class. The intercept is driven by the density instead.');
